import{_ as o,o as t,c as l,a5 as a}from"./chunks/framework.BPFk9-tb.js";const _=JSON.parse('{"title":"写作课作业-087","description":"","frontmatter":{"date":"2020-10-22T19:37:42","title":"写作课作业-087","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/087.md","filePath":"posts/homework/087.md"}'),p={name:"posts/homework/087.md"};function r(c,e,i,s,u,n){return t(),l("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《微信互联网平民创业》之《19.如何提高自己的合作性能?》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><blockquote><p>如何做才能提高自己的「可合作性」？——特简单：坚决不给他人添麻烦！</p></blockquote><blockquote><p>所谓的「不给人添麻烦」其实是很简单的，基本上只不过是「坚决不提任何额外的要求」——而相对的方法论也很简单：</p><ul><li>把所有时间精力放到「把自己份内的事儿做好」上；</li><li>同时相信对方也能做到「把自己份内的事儿做好」……</li></ul></blockquote><blockquote><p>人们总是不自觉地提很多「事实上不见得有必要的要求」。</p></blockquote><blockquote><p>通过「把自己份内事情做好」且「不向对方乱提要求」做到「坚决不给他人添麻烦」之外，高级一点的技巧无非是一个极其简单却又放在哪里都管用的思路：替别人多想一步……</p></blockquote><blockquote><p>做多了，看多了，到最后你会得到跟我一样的结论：</p><blockquote><p>大多数人的所谓「不行」，都一样，都是「没把自己份内的事情做好而已」……</p></blockquote><p>更要命的是，不仅自己份内的事情做不好，对别人要求还特别多……活的不好，都是自找的啊！</p></blockquote><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>有个同事和我说工作量很大，但公司给他什么工作，即使很晚给他提工作，他都能赶到公司去加班。这就是合作性能好的表现。</p><p>曾经自己在半夜接到客户电话也是第一时间赶到客户那，处理好问题，就睡在客户的值班室里。但为什么自己的合作性开始变差了呢？其实就是犯了「没把自己份内的事情做好，而且要求对方」的错误。</p><p>还有个同事，大家都很喜欢他，其实他就是经常站在对方的角度考虑问题，让人感觉讨论问题的时候很顺畅。</p>',11)])])}const d=o(p,[["render",r]]);export{_ as __pageData,d as default};
